import itertools

# --- Case 1: Highly structured X (Arithmetic Progression) ---
# X = {0, 4, 8, 12, 16, 20, 24}. d_x = 24.
# Required sums range: {1, ..., 49}
# Y must satisfy:
# 1. Y_min = 1 - 0 = 1
# 2. Y_max = 49 - 24 = 25
# 3. D_Y must not contain any multiple of 4 (since D_X contains all multiples of 4).

X = [0, 4, 8, 12, 16, 20, 24]
Y_min = 1
Y_max = 25
Y_candidates_pool = list(range(2, Y_max)) # {2, 3, ..., 24}

def check_Y_differences(Y):
    """Checks if Y has any difference divisible by 4."""
    for i in range(len(Y)):
        for j in range(i + 1, len(Y)):
            diff = abs(Y[j] - Y[i])
            if diff % 4 == 0:
                return False
    return True

def check_sums(X, Y):
    """Checks if the sums cover {1, ..., 49}."""
    sums = set()
    for x in X:
        for y in Y:
            sums.add(x + y)

    return len(sums) == 49 and sums == set(range(1, 50))

print("Searching for Y such that D_Y is disjoint from multiples of 4...")
solutions_found_structured_X = []

# Iterate over combinations of 5 elements for Y (since 1 and 25 are fixed)
for Y_subset in itertools.combinations(Y_candidates_pool, 5):
    Y_temp = [Y_min] + list(Y_subset) + [Y_max]
    Y_temp.sort()

    if check_Y_differences(Y_temp):
        # This set Y satisfies the distinctness condition D_X intersect D_Y = empty

        # Now check the range and coverage condition
        if check_sums(X, Y_temp):
            solutions_found_structured_X.append((X, Y_temp))

if solutions_found_structured_X:
    print("\n--- SOLUTION FOUND (Structured X Case) ---")
    print(f"X: {X}")
    print(f"Y: {solutions_found_structured_X[0]}")
else:
    print("\nNo solution found when X is an arithmetic progression {0, 4, ..., 24}.")

